function legacy($a){$t=(string)($a['title']??'');$s=(string)($a['output_summary']??'');$d=(string)($a['deliverable_type']??'');$e=(string)($a['evidence_status']??'');return $e==='legacy_archive'||in_array($d,['legacy_completion','legacy_brief'],true)||stripos($t,'Production Mission:')!==false||stripos($s,'Legacy worker completion backfilled')!==false||stripos($s,'CLICKABLE_OUTPUTS')!==false;}
function bodytxt($a){foreach(['asset_html','html','body','content','output_full','output','result','output_summary'] as $k){if(isset($a[$k])&&trim((string)$a[$k])!=='')return (string)$a[$k];}return '';}
function urlx($a){foreach(['output_url','file_url','url','public_url'] as $k){if(isset($a[$k])&&trim((string)$a[$k])!=='')return trim((string)$a[$k]);}return '';}
function atype($a,$exec){$d=strtolower((string)($a['deliverable_type']??''));$t=strtolower((string)($a['title']??''));if(str_contains($d,'blog')||str_contains($d,'article')||str_contains($d,'page'))return'Article';if(str_contains($d,'email')||str_contains($t,'email'))return'Email';if(str_contains($d,'lead')||str_contains($d,'crm')||$exec==='scout')return'Lead List';if(str_contains($d,'seo')||str_contains($d,'schema'))return'SEO Fix';if(str_contains($d,'opportunity')||str_contains($d,'sponsor')||str_contains($d,'speaking'))return'Opportunity';if(str_contains($d,'revenue')||str_contains($d,'roi'))return'Revenue';if(str_contains($d,'youtube')||str_contains($d,'thumbnail'))return'YouTube';if(str_contains($d,'audio')||str_contains($d,'music'))return'Audio';return ucfirst($d?:'Asset');}

$all=rows("SELECT * FROM goliath_deliverables WHERE executive_key=? ORDER BY created_at DESC,id DESC LIMIT 180",[$exec]);
