const KEY=<?=json_encode($key)?>, EXEC=<?=json_encode($exec)?>, ASSET_ID=<?=json_encode($selected['id']??0)?>;
async function sendStudioPrompt(mode){const isRev=mode==='revision';const el=document.getElementById(isRev?'revisePrompt':'newPrompt');const out=document.getElementById(isRev?'reviseResult':'newResult');const text=el.value.trim();if(!text){alert('Add a prompt first.');return;}out.textContent='Sending to '+EXEC+'...';try{const res=await fetch('/lead-engine/executive-studio-prompt.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:KEY,exec:EXEC,asset_id:isRev?ASSET_ID:0,mode,prompt:text})});const json=await res.json();out.textContent=(json.success||json.ok)?('Queued task #'+(json.task_id||'created')+'.'):('Error: '+(json.error||'unknown'));}catch(e){out.textContent='Error: '+e.message;}}
</script></body></html>